using Key = cuco::pair<uint32_t, int32_t>;

struct hasher {
  __device__ uint32_t operator()(Key const& k) const { return k.first; }
};

struct always_not_equal {
  __device__ constexpr bool operator()(Key const&, Key const&) const noexcept
  {
    // All build table keys are distinct thus `false` no matter what
    return false;
  }
};

class build_fn {
 public:
  __host__ __device__ constexpr build_fn(int64_t const* data) : _data{data} {}

  __device__ __forceinline__ auto operator()(int i) const noexcept
  {
    return cuco::pair{_hash(_data[i]), i};
  }

 private:
  int64_t const* _data;
  cuco::default_hash_function<int64_t> _hash{};
};

TEST_CASE("spark_test", "")
{
  using probe = cuco::linear_probing<1, hasher>;

  auto const num_keys = int(data.size());

  auto set = cuco::static_set{cuco::extent<int>{num_keys},
                              0.5,
                              cuco::empty_key<Key>{Key{std::numeric_limits<uint32_t>::max(), -1}},
                              always_not_equal{},
                              probe{},
                              {},
                              cuco::storage<1>{}};

  auto keys_begin =
    thrust::make_transform_iterator(thrust::counting_iterator{0}, build_fn{data.data().get()});

  set.insert_async(keys_begin, keys_begin + num_keys);
  auto const count = set.size();

  REQUIRE(count == num_keys);
}
